'use strict';
(() => {
  const frame = document.querySelector('.symbols-frame');
  if (!frame) return;
  const scene = frame.querySelector('.symbols-scene');
  const panel = frame.querySelector('.symbols-panel');
  const title = panel.querySelector('h3');
  const body = panel.querySelector('.symbols-panel__body');
  const close = panel.querySelector('button');
  const buttons = [...frame.querySelectorAll('[data-symbol]')];
  const layers = [...scene.querySelectorAll('.symbols-object')];
// Precomputed alpha masks also work under file://, where canvas pixel reads are blocked.
  const masks = new Map(Object.entries({"cloak":"","wolf":"","sign":""}).map(([key, value]) => [key, Uint8Array.from(atob(value), char => char.charCodeAt(0))]));
  const background = [scene, frame.querySelector('.symbols-controls'), frame.parentElement.querySelector('.symbols-heading'), ...document.querySelectorAll('main > :not(.symbols-section)')];
  const previousInert = new Map();
  let returnFocus;
  let touchInput = false;
  frame.addEventListener('pointerdown', event => {
    touchInput = event.pointerType === 'touch';
    if (touchInput) highlight();
  }, {capture:true,passive:true});
  frame.addEventListener('keydown', () => { touchInput = false; }, true);
  const highlight = key => layers.forEach(layer => layer.classList.toggle('is-highlighted', layer.dataset.layer === key));
  const hit = event => {
    const bounds = scene.getBoundingClientRect();
    if (event.clientX < bounds.left || event.clientX >= bounds.right || event.clientY < bounds.top || event.clientY >= bounds.bottom) return;
    return [...layers].reverse().find(layer => {
      // Follow the enlarged layer so its visible edge remains clickable.
      const rect = layer.getBoundingClientRect();
      const x = Math.floor((event.clientX - rect.left) / rect.width * 836);
      const y = Math.floor((event.clientY - rect.top) / rect.height * 471);
      if (x < 0 || y < 0 || x >= 836 || y >= 471) return false;
      const index = y * 836 + x;
      return Boolean(masks.get(layer.dataset.layer)[index >> 3] & (1 << (index & 7)));
    })?.dataset.layer;
  };
  function open(key, trigger) {
    const template = document.getElementById(`symbol-${key}`);
    returnFocus = trigger;
    title.textContent = template.dataset.title;
    body.replaceChildren(template.content.cloneNode(true));
    panel.hidden = false;
    buttons.forEach(button => button.setAttribute('aria-expanded', String(button.dataset.symbol === key)));
    highlight();
    scene.style.cursor = '';
    background.forEach(element => { previousInert.set(element, element.inert); element.inert = true; });
    panel.scrollTop = 0;
    close.focus({ preventScroll: true });
  }
  function dismiss() {
    panel.hidden = true;
    background.forEach(element => { element.inert = previousInert.get(element) || false; });
    buttons.forEach(button => button.setAttribute('aria-expanded', 'false'));
    returnFocus?.focus({ preventScroll: true });
  }
  buttons.forEach(button => {
    button.addEventListener('click', () => open(button.dataset.symbol, button));
    button.addEventListener('pointerenter', event => { if (event.pointerType !== 'touch') highlight(button.dataset.symbol); });
    button.addEventListener('pointerleave', () => highlight());
    button.addEventListener('focus', () => { if (!touchInput) highlight(button.dataset.symbol); });
    button.addEventListener('blur', () => highlight());
  });
  scene.addEventListener('pointermove', event => {
    if (event.pointerType === 'touch') { highlight(); return; }
    const key = hit(event);
    highlight(key);
    scene.style.cursor = key ? 'pointer' : '';
  });
  scene.addEventListener('pointerleave', () => highlight());
  scene.addEventListener('pointercancel', () => highlight());
  scene.addEventListener('pointerup', event => { if (event.pointerType === 'touch') highlight(); });
  scene.addEventListener('click', event => {
    const key = hit(event);
    if (key) open(key, buttons.find(button => button.dataset.symbol === key));
  });
  close.addEventListener('click', dismiss);
  panel.addEventListener('keydown', event => {
    if (event.key === 'Escape') { event.preventDefault(); dismiss(); }
    if (event.key === 'Tab') {
      const focusable = [...panel.querySelectorAll('button, a[href]')];
      const first = focusable[0], last = focusable.at(-1);
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    }
  });
})();
